    def test_summarize_rank_coverage_counts_drops_docnote_slots_early(self):
        rank_map = nnf.build_rank_map(
            (
                frozenset({"נוסח"}),
                frozenset({"כו״ק"}),
            )
        )
        stack_counts = {
            # Without early slot dropping this path would be partially_checked
            # (stack len=3 vs ranked len=2). With early dropping it is len=2,
            # so the same ranked path is fully_checked.
            ("כו״ק", "E/נוסח/נוסח@1"): 5,
            # This path becomes singleton after slot dropping and is therefore
            # excluded from coverage totals.
            ("כו״ק", "D/נוסח@2"): 7,
        }

        summary = nnf.summarize_rank_coverage_counts(stack_counts, rank_map)
        self.assertEqual(
            {
                "fully_checked": 5,
                "partially_checked": 0,
                "totally_unchecked": 0,
                "total": 5,
            },
            summary,
        )

    def test_summarize_rank_coverage_top_paths_returns_counts_per_bucket(self):
        rank_map = nnf.build_rank_map(
            (
                frozenset({"A"}),
                frozenset({"B"}),
                frozenset({"C"}),
            )
        )
        stack_counts = {
            # stack X/A (rest X + top A) projects to A (len=1)
            # => totally unchecked
            ("A", "E/X"): 7,
            # fully checked
            ("C", "E/A/B"): 2,
            # partially checked
            ("C", "E/A/X"): 3,
            ("C", "E/A/Y"): 5,
            # totally unchecked
            ("Z", "E/X/Y"): 5,
            ("Z", "E/Y/X"): 1,
        }
        top_paths = nnf.summarize_rank_coverage_top_paths(
            stack_counts,
            rank_map,
            max_paths=1,
        )
        self.assertEqual(1, len(top_paths["fully_checked"]))
        self.assertIn("stack", top_paths["fully_checked"][0])
        self.assertEqual("E/A/B/C", _read_top_stack(top_paths["fully_checked"][0]))
        self.assertEqual(2, top_paths["fully_checked"][0]["count"])

        self.assertEqual(1, len(top_paths["partially_checked"]))
        self.assertIn("stack", top_paths["partially_checked"][0])
        self.assertEqual("E/A/Y/C", _read_top_stack(top_paths["partially_checked"][0]))
        self.assertEqual(5, top_paths["partially_checked"][0]["count"])

        self.assertEqual(1, len(top_paths["totally_unchecked"]))
        self.assertIn("stack", top_paths["totally_unchecked"][0])
        self.assertEqual("E/X/A", _read_top_stack(top_paths["totally_unchecked"][0]))
        self.assertEqual(7, top_paths["totally_unchecked"][0]["count"])

